import json, hashlib
from pathlib import Path
base=Path('work/continuation2')
p=json.loads((base/'patches/rmd2.json').read_text())
def refs(eids):
 out=[]
 for table in ('evidence','passages','assertions','relationships','boons_and_powers','narrative_events'):
  for r in p.get(table,[]):
   if r.get('id') in eids or set(r.get('evidence_ids',[]))&set(eids): out.append({'table':table,'id':r['id']})
 return out
findings=[]
def add(id,status,locator,eids,finding,requested=None,record_ids=None):
 findings.append({'id':id,'status':status,'source_id':'gp-src-mudgala','witness_id':'gp-wit-sd-mudgala-1','locator':locator,'evidence_ids':eids,'records':refs(eids) if record_ids is None else record_ids,'finding':finding,'requested_correction':requested})
add('gup2-review-rmd2-001','SUPPORTED','Mudgala 1.3.61–63',['rmd2-e-sati-death-rebirth'],'Yoga-fire body abandonment, own-māyā reappearance as Himācala’s daughter, Śiva meditation, severe tapas and renewed husband relationship are explicit. Daughter relation and rebirth must retain their distinct source contexts.')
add('gup2-review-rmd2-002','SUPPORTED','Mudgala 1.4.41–47',['rmd2-e-virabhadra-origin'],'The source explicitly gives three heads, three feet and trident, arising from Śiva’s struck matted hair while Gaṇeśa is remembered. Servant declaration, command against Dakṣa with sacrifice, world-shaking laugh, body-generated Rudras and following Gaṇas are supported; this is manifestation rather than ordinary biological birth.')
add('gup2-review-rmd2-003','SUPPORTED','Mudgala 1.4.56–64',['rmd2-e-sacrifice-duels'],'The named duel assignments and actions match the Sanskrit. Bhairava makes Indra unconscious; Śiva, rather than Vīrabhadra, breaks Pūṣan’s teeth and removes Bhaga’s eyes. Nandin seizes Dharma, Bhṛṅgin Kaśyapa, Puṣpadanta strikes Varuṇa, Vīrabhadra fells Dakṣa, and Śiva fells Viṣṇu with heart-directed arrows after Gaṇeśa contemplation.')
add('gup2-review-rmd2-004','SUPPORTED','Mudgala 1.4.65–72',['rmd2-e-missile-counter-beheading'],'Nārāyaṇa and Pāśupata missiles fight in the sky; their fire and frightened worlds, Dakṣa’s head offered into fire by Vīrabhadra, and cakra bowing and stopping before Śiva are supported. The beast comparison is locally ritual framing, not a goat-head precondition.')
add('gup2-review-rmd2-005','SUPPORTED','Mudgala 1.4.73–85',['rmd2-e-battle-halted'],'Heavenly voice remains unidentified. Viṣṇu survives the intended trident attack; Brahmā pacifies Śiva, assigns remaining offerings and requests restoration. Bhaga gets eyes, Pūṣan becomes a ground-food eater, and other attendees regain their former forms/radiance.')
add('gup2-review-rmd2-006','SUPPORTED','Mudgala 1.4.86–90',['rmd2-e-daksha-goat-revival'],'The burnt head causes the first-seen-being head instruction. Bhṛṅgin kills the seen goat, Śiva attaches the head and revives Dakṣa, and Brahmā prompts the hymn. Goat-head revival is an intermediate event.')
add('gup2-review-rmd2-007','SUPPORTED','Mudgala 1.4.97,101–107',['rmd2-e-daksha-human-head-restored'],'The pardon request, goat-like voiced praise, subsequent human-head restoration, announced Prajāpati chiefship and separate hymn/sound benefits are explicit. The witness does not leave Dakṣa permanently goat-headed. Once qualifies the goat-like sound before Śiva; no numerical repetition restriction is given for the hymn here.')
add('gup2-review-rmd2-008','SUPPORTED','Mudgala 1.11.7–9',['rmd2-e-five-emergence'],'All five emanation sites are supported: navel, mouth, eye, left side and right side. Śiva explicitly addresses Pārvatī as Śakti in this cosmic narrative. COSMOLOGICAL_EMANATION and the local speech qualifier correctly preserve this without replacing the Himācala daughter/rebirth account.')
add('gup2-review-rmd2-009','SUPPORTED','Mudgala 1.11.63–68',['rmd2-e-five-duties-boons'],'Brahmā’s haṃsa, Viṣṇu’s Garuḍa and Hara’s bull, together with their named stations/functions and four-face/four-arm/five-face qualifications, are supported. Third-eye burning is explicitly assigned to Hara.')
add('gup2-review-rmd2-010','SUPPORTED','Mudgala 1.11.69–76',['rmd2-e-five-duties-boons'],'Sūrya’s horse-adorned chariot and Śakti’s lion match this text; no horse number is supplied. Thousand rays, six seasons, rain source, Sauraloka and Śaktiloka are explicit. Weapons, ornaments, varied powers and fulfilled resolve are a collective final grant.')
add('gup2-review-rmd2-011','CORRECTION_PENDING','Mudgala 1.11.15–18',['rmd2-e-five-emergence','rmd2-e-five-manifestation-hymn'],'All five grant records include the inwardly revealed seed-mantra in austerity_or_circumstances, but its field citation only points to 1.11.18–51, excluding 15–17. Record-level evidence already includes the needed passage.','Add rmd2-e-five-emergence to field_evidence.austerity_or_circumstances on all five rmd2-power-five-grant-* records; retain manifestation-hymn for 1,000 divine years and hymn.',[{'table':'boons_and_powers','id':'rmd2-power-five-grant-'+s} for s in ('brahma','vishnu','hara','surya','shakti')])
add('gup2-review-rmd2-012','CORRECTION_PENDING','Mudgala 1.4.64–65',['rmd2-e-sacrifice-duels','rmd2-e-missile-counter-beheading'],'The sacrifice-duels event outcome says Viṣṇu then regains awareness; that occurs in verse65, beyond its cited 56–64 span.','Add rmd2-e-missile-counter-beheading and its passage to rmd2-event-sacrifice-duels, or keep this event outcome at being felled and place recovery exclusively in the next event.',[{'table':'narrative_events','id':'rmd2-event-sacrifice-duels'}])
add('gup2-review-rmd2-013','CORRECTION_PENDING','Mudgala 1.3.61–63;1.4.1–14,38',['rmd2-e-sati-death-rebirth'],'Chapter3 anticipates the Pārvatī rebirth/remarriage in a compact narrator summary; chapter4 returns to Śiva responding to Satī’s death and explicitly predicts the Himācala birth. The current outcome calls the rebirth a retrospective summary without identifying this source-order rewind.','Revise outcome to identify the chapter3 advance summary and chapter4 return to the earlier death-aftermath, keeping source sequence distinct from reconstructed chronology.',[{'table':'narrative_events','id':'rmd2-event-sati-death-rebirth'}])
add('gup2-review-rmd2-014','CORRECTION_PENDING','Mudgala 1.4.104–107',['rmd2-e-daksha-human-head-restored'],'The restrictions field currently contains an editorial caution, while the actual once/before Śiva requirement is accurately present in trigger.','Set restrictions to null, move the editorial caution into notes, and retain the explicit sound condition in trigger. Alternatively restrict this field to the explicit local ritual condition only.',[{'table':'boons_and_powers','id':'rmd2-power-daksha-shiva-hymn-reward'}])
review={'review_id':'gup2-review-rmd2','reviewer':'Upāsanā continuation agent /root/lalitopakhyana','reviewed_patch':'work/continuation2/patches/rmd2.json','reviewed_sha256':hashlib.sha256((base/'patches/rmd2.json').read_bytes()).hexdigest(),'source_url':'https://sanskritdocuments.org/doc_purana/mudgalapurANam1.html','method':'Independent direct Sanskrit body reading, then comparison with concrete patch rows. No root file edited.','read_spans':['1.3.61–63','1.4.1–110','1.11.1–78'],'scope':'Requested critical facts and associated citations only; does not certify all names/all chapters or another edition.','summary':{'SUPPORTED':10,'CORRECTION_PENDING':4,'PENDING':0},'findings':findings,'limitations':['Single Sanskrit Documents witness only; no alternate/print witness independently collated.','No whole-patch or whole-Mudgala extraction-completeness certification.','1.11 web numbering repeats verse32 in the hymn; outside critical requested loci, not silently normalized.']}
